import React from 'react';
import Reveal from './Reveal';
import SectionHeading from './SectionHeading';
import { beliefs } from '../data/content';

export default function Believe() {
  return (
    <section id="believe" className="py-16 px-6 border-t border-zinc-100">
      <div className="max-w-prose mx-auto">
        <Reveal>
          <SectionHeading eyebrow="Believe" heading={beliefs.heading} />
        </Reveal>

        <Reveal delay={60}>
          <p className="mt-2 text-xs font-mono text-amber-600 bg-amber-50 inline-block px-2 py-1 rounded">
            {beliefs.note}
          </p>
        </Reveal>

        <ul className="mt-5 space-y-3">
          {beliefs.items.map((item, idx) => (
            <Reveal key={item} delay={100 + idx * 60}>
              <li className="flex gap-3 text-zinc-600 leading-relaxed">
                <span className="text-orange-400">—</span>
                {item}
              </li>
            </Reveal>
          ))}
        </ul>
      </div>
    </section>
  );
}
